-- PKG_DMF0020 — 적용 후 확인 (SCM_MGR · 조회 전용)
SET PAGESIZE 200 LINESIZE 300

SELECT 'PKG_DMF0020' OBJ, 'PACKAGE' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0020' AND OBJECT_TYPE = 'PACKAGE') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'PKG_DMF0020' AND TYPE = 'PACKAGE' AND LINE > 1) = 499915707741 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT 'PKG_DMF0020' OBJ, 'PACKAGE BODY' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0020' AND OBJECT_TYPE = 'PACKAGE BODY') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'PKG_DMF0020' AND TYPE = 'PACKAGE BODY' AND LINE > 1) = 19497835517125 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL' OBJ, 'PROCEDURE' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL' AND OBJECT_TYPE = 'PROCEDURE') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL' AND TYPE = 'PROCEDURE' AND LINE > 1) = 2191934432770 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP' OBJ, 'PROCEDURE' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP' AND OBJECT_TYPE = 'PROCEDURE') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP' AND TYPE = 'PROCEDURE' AND LINE > 1) = 1505122455340 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL', 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP', 'PKG_DMF0020') ORDER BY NAME, TYPE, SEQUENCE;
SELECT OBJECT_NAME PKG, PROCEDURE_NAME MEMBER FROM USER_PROCEDURES WHERE OBJECT_NAME = 'PKG_DMF0020' AND PROCEDURE_NAME IN ('P_PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE') ORDER BY 2;  -- 기대 1행
SELECT OBJECT_NAME, OBJECT_TYPE FROM USER_OBJECTS WHERE STATUS = 'INVALID' AND OBJECT_TYPE IN ('PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION') ORDER BY 1;
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_DMF0020';
